from collections import deque

def sliding_max(xs, w):
    if w < 1:
        raise ValueError("window width must be at least 1")
    if w > len(xs):
        return []

    result = []
    candidates = deque()

    for i, value in enumerate(xs):
        while candidates and candidates[0] <= i - w:
            candidates.popleft()

        while candidates and xs[candidates[-1]] <= value:
            candidates.pop()

        candidates.append(i)

        if i >= w - 1:
            result.append(xs[candidates[0]])

    return result
